// Writes the two files to paste into the Supabase SQL editor, one after the other: npm run db:bundle
//   1. supabase/paste_1_schema.sql : migrations 001 to 005 in one transaction. Re-runnable, keeps data.
//   2. supabase/paste_2_seed.sql   : the seed (wipes and rebuilds the demo data).
import { readFileSync, writeFileSync } from "node:fs";

const migrations = [
  "supabase/migrations/001_schema.sql",
  "supabase/migrations/002_work_functions.sql",
  "supabase/migrations/003_agent_functions.sql",
  "supabase/migrations/004_corner_cases.sql",
  "supabase/migrations/005_tasks_versions.sql",
];

const header = (n) =>
  `-- Generated by "npm run db:bundle" (paste ${n} of 2). Do not edit or commit; edit the source files instead.\n` +
  "-- Paste the WHOLE file into an empty Supabase SQL editor tab and press Run.\n\n";
const section = (f) => `-- >>>>>>>> ${f}\n${readFileSync(f, "utf8").trim()}\n`;

const schema = "supabase/paste_1_schema.sql";
writeFileSync(
  schema,
  `${header(1)}begin;\n\n${migrations.map(section).join("\n")}\ncommit;\n\n` +
    "select 'schema ok' as result, count(*) as tables from pg_tables where schemaname = 'public';\n",
);

const seed = "supabase/paste_2_seed.sql";
writeFileSync(seed, `${header(2)}${section("supabase/seed.sql")}`);

console.log(`Wrote ${schema} and ${seed}. Run them in the Supabase SQL editor in that order.`);
